const raw = $('Trigger').item.json.payload;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : raw;
return [{ json: ctx }];

const ctx = $('Parsear input').item.json;
const services = $('Buscar serviço').item.json || [];

if (!services.length) {
  return [{ json: { 
    ...ctx,
    error: 'service_not_found',
    confirmation_message: `Desculpe, não encontrei o serviço "${ctx.action_data.service_name}". Pode me dizer qual serviço você deseja?`
  }}];
}

const service = services[0];

// Calcular janela de busca
const preferredDate = ctx.action_data.preferred_date;
const now = new Date();
let searchFrom = new Date(now);
searchFrom.setHours(now.getHours() + 1, 0, 0, 0); // mínimo 1h de antecedência

if (preferredDate && preferredDate !== 'null') {
  searchFrom = new Date(preferredDate + 'T00:00:00');
  if (searchFrom < now) searchFrom = now;
}

const searchTo = new Date(searchFrom);
searchTo.setDate(searchTo.getDate() + 14);

return [{
  json: {
    ...ctx,
    service,
    search_from: searchFrom.toISOString(),
    search_to: searchTo.toISOString()
  }
}];

const ctx = $('Preparar busca').item.json;
const busySlots = $('Buscar horários ocupados').item.json || [];
const openingHours = ctx.tenant.opening_hours || {};
const durationMin = ctx.service.duration_minutes;
const preferredTime = ctx.action_data.preferred_time;

const dayKeys = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const availableSlots = [];

const searchFrom = new Date(ctx.search_from);
const searchTo = new Date(ctx.search_to);

for (let d = new Date(searchFrom); d < searchTo && availableSlots.length < 4; d.setDate(d.getDate() + 1)) {
  const dayKey = dayKeys[d.getDay()];
  const hours = openingHours[dayKey];
  if (!hours || !hours.open) continue;

  const [openH, openM] = (hours.start || '08:00').split(':').map(Number);
  const [closeH, closeM] = (hours.end || '18:00').split(':').map(Number);

  // Se tem horário preferido, começar por ele
  let startHour = openH;
  let startMin = openM;
  if (preferredTime && preferredTime !== 'null') {
    const [ph, pm] = preferredTime.split(':').map(Number);
    if (ph >= openH && ph < closeH) {
      startHour = ph;
      startMin = pm || 0;
    }
  }

  let slotStart = new Date(d);
  slotStart.setHours(startHour, startMin, 0, 0);

  const dayEnd = new Date(d);
  dayEnd.setHours(closeH, closeM, 0, 0);

  // Garantir que não é no passado
  const now = new Date();
  if (slotStart < now) slotStart = new Date(Math.ceil(now.getTime() / (30*60000)) * (30*60000));

  while (slotStart < dayEnd && availableSlots.length < 4) {
    const slotEnd = new Date(slotStart.getTime() + durationMin * 60000);
    if (slotEnd > dayEnd) break;

    const hasConflict = busySlots.some(b => {
      const bStart = new Date(b.start_time);
      const bEnd = new Date(b.end_time);
      return slotStart < bEnd && slotEnd > bStart;
    });

    if (!hasConflict) {
      const label = slotStart.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: '2-digit' }) +
                    ' às ' + slotStart.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
      availableSlots.push({
        starts_at: slotStart.toISOString(),
        ends_at: slotEnd.toISOString(),
        label
      });
    }

    slotStart = new Date(slotStart.getTime() + 30 * 60000); // avançar 30min
  }
}

if (availableSlots.length === 0) {
  return [{ json: {
    ...ctx,
    available_slots: [],
    confirmation_message: `Não encontrei horários disponíveis para ${ctx.service.name} nos próximos dias. Pode tentar outra data?`
  }}];
}

// Se só tem 1 slot (intenção de horário específico), agendar direto
// Se tem múltiplos, oferecer as 3 primeiras opções
const slotsText = availableSlots.slice(0, 3).map((s, i) => `${i+1}. ${s.label}`).join('\n');

return [{
  json: {
    ...ctx,
    available_slots: availableSlots,
    best_slot: availableSlots[0],
    slots_text: slotsText,
    // Se pediu horário específico e encontrou, agendar diretamente
    auto_book: !!(ctx.action_data.preferred_date && ctx.action_data.preferred_time && availableSlots.length > 0)
  }
}];

const ctx = $json;
// Oferecer opções ao cliente
const response = `Ótimo! Tenho estes horários disponíveis para *${ctx.service.name}*:

${ctx.slots_text}

Qual prefere? 😊`;
return [{ json: { ...ctx, confirmation_message: response, booked: false } }];

const ctx = $('Calcular slots disponíveis').item.json;
const appointment = $('Criar agendamento').item.json;
const slot = ctx.best_slot;

const dateLabel = new Date(slot.starts_at).toLocaleDateString('pt-BR', { 
  weekday: 'long', day: '2-digit', month: 'long' 
});
const timeLabel = new Date(slot.starts_at).toLocaleTimeString('pt-BR', { 
  hour: '2-digit', minute: '2-digit' 
});

const response = `✅ *Agendamento confirmado!*\n\n` +
  `📋 ${ctx.service.name}\n` +
  `📅 ${dateLabel}\n` +
  `🕐 ${timeLabel}\n` +
  `💰 R$ ${Number(ctx.service.price).toFixed(2)}\n\n` +
  `Qualquer dúvida é só chamar! Até lá 😊`;

return [{ json: { ...ctx, confirmation_message: response, booked: true } }];
